            NextflowProcess.executeSession(List.of(python.toString(),"-I","-S","-B",root.resolve("bind_runtime.py").toString(),root.toString()),env,root.resolve("process"),root,root,limits,()->{selections(spec,id,check);require(Arrays.equals(raw,bytes(request,16777216)),"Binding request changed");},check);
            MerquryRuntime.verifyInventory(object(json(root.resolve("inventory.json"),134217728)),check);selections(spec,id,check);writeJson(root.resolve("manifest.json"),map("profile",id,"producer",producer(),"files",manifest(tree(root,20000,2147483648L,268435456,check))));writeJson(root.resolve("COMPLETED.json"),map("status","COMPLETE_GRAPHTYPER_RUNTIME_BINDING_ONLY","manifest",pin(root.resolve("manifest.json"),16777216,check),"analysis_admitted",false));open(root,id,check);return root;
